using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;using Microsoft.Win32.SafeHandles;
namespace ClearDisk {
 internal sealed class StructuredBackupEntry {
  internal string Id,OriginalPath,Kind,State,Error;internal long Bytes;internal DateTime CreatedUtc;
 }
 internal sealed class StructuredBackupStore {
  internal sealed class Receipt {
   public int Version=1;public string Id,Path,Kind,Hash,Context,State;public long Bytes,WriteTicks,PostWriteTicks;public uint Volume;public ulong FileId;public DateTime CreatedUtc;public StructuredRegistrySnapshot Registry;
  }
  static readonly byte[] entropy=Encoding.UTF8.GetBytes("ClearDisk frozen cleanup backup v1");static readonly Encoding utf8=new UTF8Encoding(false,true);
  internal readonly string Root;
  internal StructuredBackupStore(string root){Root=NativeFiles.Normalize(root);if(Root.Length<5)throw new IOException("备份目录不能是卷根。");}
  internal bool Contains(string path){return SafetyPolicy.IsWithin(path,Root);}
  internal static void EnsureDirectory(string directory){string full=NativeFiles.Normalize(directory),current=full.Substring(0,3);foreach(string part in full.Substring(3).Split('\\')){string next=Path.Combine(current,part);using(var pin=new NativeFiles.ParentLocks(next)){Directory.CreateDirectory(next);}current=next;}using(var pin=new NativeFiles.ParentLocks(Path.Combine(full,".pin"))){} }
  static void Id(string value){if(value==null||!System.Text.RegularExpressions.Regex.IsMatch(value,@"\A[a-f0-9]{32}\z"))throw new IOException("备份身份无效。");}
  string PathOf(string id,string suffix){Id(id);return Path.Combine(Root,id+suffix);}
  void Write(Receipt receipt,bool post){byte[] data=ProtectedData.Protect(utf8.GetBytes(Json().Serialize(receipt)),entropy,DataProtectionScope.CurrentUser);string path=PathOf(receipt.Id,post?".post":".receipt");using(var pins=new NativeFiles.ParentLocks(path))using(var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None,4096,FileOptions.WriteThrough)){stream.Write(data,0,data.Length);stream.Flush(true);} }
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=16777216,RecursionLimit=256};}
  static void CheckStorage(SafeFileHandle h,string path){var i=NativeFiles.Info(h);if(i.Links!=1||(i.Attributes&0x410)!=0||!String.Equals(NativeFiles.Final(h),path,StringComparison.OrdinalIgnoreCase))throw new IOException("备份路径或链接异常。");}
  Receipt Read(string id){string path=PathOf(id,".post");if(!File.Exists(path))path=PathOf(id,".receipt");using(var pin=new NativeFiles.ParentLocks(path))using(var handle=NativeFiles.OpenData(path,false)){CheckStorage(handle,path);long size=NativeFiles.Stamp(handle).Length;if(size<1||size>16777216)throw new IOException("备份凭据大小异常。");using(var data=new MemoryStream()){StructuredFileIo.Copy(handle,data);var receipt=Json().Deserialize<Receipt>(utf8.GetString(ProtectedData.Unprotect(data.ToArray(),entropy,DataProtectionScope.CurrentUser)));if(receipt==null||receipt.Version!=1||receipt.Id!=id||receipt.Context!=CompatibleCleanupEngine.CurrentContext())throw new IOException("备份凭据来源或用户/权限不同。");if(receipt.Registry==null){NativeFiles.Normalize(receipt.Path);if(Contains(receipt.Path)||StructuredCleanupEngine.ProtectedArtifact(receipt.Path)||receipt.Bytes<0||String.IsNullOrEmpty(receipt.Hash)||Convert.FromBase64String(receipt.Hash).Length!=32)throw new IOException("备份凭据目标无效。");}return receipt;}}}
  internal string SaveFile(SafeFileHandle source,StructuredFile file,string kind){EnsureDirectory(Root);var s=NativeFiles.Stamp(source);var receipt=new Receipt{Id=Guid.NewGuid().ToString("N"),Path=file.Path,Kind=kind,Hash=file.Hash,Context=CompatibleCleanupEngine.CurrentContext(),State="Prepared",Bytes=file.Bytes,Volume=s.Volume,FileId=s.FileId,WriteTicks=s.LastWriteTicks,CreatedUtc=DateTime.UtcNow};string target=PathOf(receipt.Id,".data");using(var pins=new NativeFiles.ParentLocks(target)){using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None,65536,FileOptions.WriteThrough)){StructuredFileIo.Copy(source,output);output.Flush(true);}using(var verify=NativeFiles.OpenData(target,false)){CheckStorage(verify,target);if(NativeFiles.Hash(verify,CancellationToken.None)!=receipt.Hash)throw new IOException("备份内容校验失败，原文件保留。");}Write(receipt,false);}return receipt.Id;}
  internal string SaveRegistry(StructuredRegistrySnapshot registry){EnsureDirectory(Root);var r=new Receipt{Id=Guid.NewGuid().ToString("N"),Path=registry.Key,Kind="Winreg",Context=CompatibleCleanupEngine.CurrentContext(),State="Prepared",Registry=registry,CreatedUtc=DateTime.UtcNow};Write(r,false);return r.Id;}
  internal string JournalFile(StructuredFile file,string kind){EnsureDirectory(Root);var s=file.Stamp;var r=new Receipt{Id=Guid.NewGuid().ToString("N"),Path=file.Path,Kind=kind,Hash=file.Hash,Context=CompatibleCleanupEngine.CurrentContext(),State="NotRecoverable",Bytes=file.Bytes,Volume=s.Volume,FileId=s.FileId,WriteTicks=s.LastWriteTicks,CreatedUtc=DateTime.UtcNow};Write(r,false);return r.Id;}
  internal void MarkTruncated(string id,FileStamp post){var receipt=Read(id);receipt.PostWriteTicks=post.LastWriteTicks;receipt.State="Truncated";Write(receipt,true);}
  internal StructuredBackupEntry[] List(){if(!Directory.Exists(Root))return new StructuredBackupEntry[0];var result=new List<StructuredBackupEntry>();using(var pin=new NativeFiles.ParentLocks(Path.Combine(Root,".pin")))foreach(string path in Directory.GetFiles(Root,"*.receipt")){string id=Path.GetFileNameWithoutExtension(path);try{var r=Read(id);result.Add(new StructuredBackupEntry{Id=id,OriginalPath=r.Path,Kind=r.Kind,State=r.State,Bytes=r.Bytes,CreatedUtc=r.CreatedUtc});}catch(Exception e){if(!StructuredCleanupEngine.Expected(e))throw;result.Add(new StructuredBackupEntry{Id=id,State="Invalid",Error=e.Message});}}return result.OrderByDescending(r=>r.CreatedUtc).ToArray();}
  internal bool Restore(string id,out string reason){try{var receipt=Read(id);if(receipt.State=="NotRecoverable")throw new IOException("此操作经明确选择未备份文件内容，仅保留审计记录，无法恢复。");if(receipt.Registry!=null){receipt.Registry.RestoreFrozen();reason="已恢复原设置；已有键或值时拒绝覆盖。";return true;}string data=PathOf(id,".data");using(var bp=new NativeFiles.ParentLocks(data))using(var op=new NativeFiles.ParentLocks(receipt.Path))using(var input=NativeFiles.OpenData(data,false)){CheckStorage(input,data);if(NativeFiles.Stamp(input).Length!=receipt.Bytes||NativeFiles.Hash(input,CancellationToken.None)!=receipt.Hash)throw new IOException("备份内容哈希不匹配。");
    if(receipt.Kind=="Truncate"){
     if(receipt.State!="Truncated")throw new IOException("截断后的状态未持久确认，拒绝自动覆盖；备份保留。");
     using(var output=StructuredFileIo.OpenMutation(receipt.Path,true)){StructuredCleanupEngine.CheckFile(NativeFiles.Info(output));var s=NativeFiles.Stamp(output);if(s.Volume!=receipt.Volume||s.FileId!=receipt.FileId||s.Length!=0||s.Links!=1||s.LastWriteTicks!=receipt.PostWriteTicks||!String.Equals(s.FinalPath,receipt.Path,StringComparison.OrdinalIgnoreCase))throw new IOException("原位置已变化，拒绝覆盖。");using(var borrowed=new SafeFileHandle(output.DangerousGetHandle(),false))using(var stream=new FileStream(borrowed,FileAccess.Write)){stream.Position=0;StructuredFileIo.Copy(input,stream);stream.Flush(true);}}
    }else{
     if(File.Exists(receipt.Path)||Directory.Exists(receipt.Path))throw new IOException("原位置已有内容，拒绝覆盖。");string temp=Path.Combine(Path.GetDirectoryName(receipt.Path),".cdrestore-"+Guid.NewGuid().ToString("N"));
     using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None,65536,FileOptions.WriteThrough)){StructuredFileIo.Copy(input,output);output.Flush(true);}using(var output=NativeFiles.OpenData(temp,true)){CheckStorage(output,temp);if(NativeFiles.Hash(output,CancellationToken.None)!=receipt.Hash)throw new IOException("恢复暂存内容校验失败。");NativeFiles.Rename(output,receipt.Path);}
    }
   }reason="已恢复内容；备份继续保留。ACL、外部程序状态及系统维护不属于文件回滚。";return true;}catch(Exception e){if(!StructuredCleanupEngine.Expected(e))throw;reason=e.Message;return false;}}
 }
}
